package org.eclipse.debug.internal.core;

import org.eclipse.core.resources.IFile;
import org.eclipse.core.resources.ProjectScope;
import org.eclipse.core.runtime.Platform;
import org.eclipse.core.runtime.preferences.IScopeContext;
import org.eclipse.core.runtime.preferences.InstanceScope;
import org.eclipse.core.resources.ResourcesPlugin; // Keep for negative example context

// Minimal dummy types to satisfy compilation for the before example
interface DummyIFile extends IFile {
    default DummyProject getProject() { return null; }
}
class DummyProject {
    // Empty
}
interface IScopeContext {}
class ProjectScope implements IScopeContext {
    public ProjectScope(Object project) {}
}
class InstanceScope implements IScopeContext {
    public static final InstanceScope INSTANCE = new InstanceScope();
}
class DummyPlatform {
    public static final String PI_RUNTIME = "org.eclipse.core.runtime";
    public static final String PREF_LINE_SEPARATOR = "line.separator";
    public static PreferencesService getPreferencesService() {
        return new PreferencesService();
    }
}
class PreferencesService {
    public String getString(String pluginId, String key, String defaultValue, IScopeContext[] scopeContexts) {
        return System.lineSeparator(); // Mock behavior
    }
}

public class LaunchConfiguration {
    private static String getLineDelimiterPreference(IFile file) {
        IScopeContext[] scopeContext;
        if (file != null && ((DummyIFile)file).getProject() != null) {
            scopeContext = new IScopeContext[] {
                    new ProjectScope(((DummyIFile)file).getProject()) };
            String lineDelimiter = DummyPlatform.getPreferencesService().getString(DummyPlatform.PI_RUNTIME, DummyPlatform.PREF_LINE_SEPARATOR, null, scopeContext);
            if (lineDelimiter != null) {
                return lineDelimiter;
            }
        }
        scopeContext = new IScopeContext[] { InstanceScope.INSTANCE };
        return DummyPlatform.getPreferencesService().getString(DummyPlatform.PI_RUNTIME, DummyPlatform.PREF_LINE_SEPARATOR, null, scopeContext);
    }

    public String getMemento(IFile file) throws Exception {
        String lineDelimeter = getLineDelimiterPreference(file);
        return lineDelimeter;
    }

    public void otherMethod(IFile file) {
        String anotherDelimiter = getLineDelimiterPreference(file);
        System.out.println(anotherDelimiter);
    }
}

